import psutil
from collections import defaultdict

def get_cpu_usage(pid):
    """Get CPU usage of a process by PID."""
    try:
        process = psutil.Process(pid)
        return process.cpu_percent(interval=1) / psutil.cpu_count()
    except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
        return None

def find_long_running_processes(threshold=90, timeout=300):
    """Find processes that exceed the CPU usage threshold for more than a given timeout."""
    long_running = defaultdict(list)

